function worldViewportRect(pad=0){let pts=[[0,0],[W,0],[0,H],[W,H]].map(([clientX,clientY])=>toWorld({clientX,clientY}));return {left:Math.min(...pts.map(p=>p.x))-pad,right:Math.max(...pts.map(p=>p.x))+pad,top:Math.min(...pts.map(p=>p.y))-pad,bottom:Math.max(...pts.map(p=>p.y))+pad};}

const $=id=>document.getElementById(id), cv=$('map');let ctx=cv.getContext('2d');
const COLORS=['#4e94b7','#d39a42','#9578ac'], LINECOL=['#d36951','#4b9292','#777bb4','#c6a342','#8f6f9b','#72a46e','#bd7e9b','#6388a9'];
const TYPES={bus:{name:'大巴',short:'巴',speed:32,cap:14,transfer:1.5,vehicle:180,line:0,icon:'▣'},rail:{name:'高铁',short:'铁',speed:72,cap:18,transfer:4,vehicle:900,line:0,icon:'▤'},air:{name:'航空',short:'航',speed:150,cap:48,transfer:6,vehicle:1600,line:0,icon:'✈'}};
const coast=y=>typeof activeAtlasMap!=='undefined'&&activeAtlasMap?1e9:1050+24*Math.sin(y/138)+9*Math.sin(y/43)-.13*y;
const river=y=>{if(typeof activeAtlasMap!=='undefined'&&activeAtlasMap){let p=activeAtlasMap.main;for(let i=1;i<p.length;i++)if(y<=p[i][1])return p[i-1][0]+(p[i][0]-p[i-1][0])*(y-p[i-1][1])/(p[i][1]-p[i-1][1]);return p.at(-1)[0];}return 570+65*Math.sin(y/150)+.2*y;};
const mountains=typeof activeAtlasMap!=='undefined'&&activeAtlasMap?atlasClone(activeAtlasMap.mountains):[{x:190,y:155,rx:155,ry:55},{x:540,y:130,rx:125,ry:57},{x:825,y:170,rx:150,ry:65}];
const hills=typeof activeAtlasMap!=='undefined'&&activeAtlasMap?atlasClone(activeAtlasMap.hills):[{x:320,y:555,rx:200,ry:85},{x:745,y:570,rx:165,ry:90}];
const names=['松原','河西','云川','临江','青浦','北麓','海宁','南溪','东临','栖山','锦州','望海','榆川','石桥','鹿谷','平川','晴岚','新浦','长宁','清河','雾岭','南庭','林川','远山','安平','禾城','临海','澄江','桃源','江湾'];
let popEvents=[];const vehicleVisuals=new Map();let junctionOpen=false;
let lastPanelSignature='',portraitMode=false,orientationHintDismissed=false,stopUndo=null;
let S,view={scale:1,x:0,y:0,rot:0},W,H,dpr,selected=null,draft=null,gesture=null,pointers=new Map(),modalOpen=false,toastTimer,drawFrame=0,last=performance.now(),detailClock=0;
function rand(a,b){return a+Math.random()*(b-a)}
function fresh(){return {version:1,economyVersion:3,day:0,delivered:0,periodDelivered:0,points:5000,moneyScale:10,lives:2,speed:1,paused:true,cities:[],lines:[],vehicles:[],nextP:1,nextV:1,nextL:1,inventory:{bus:0,rail:0,air:0,bridge:0,tunnel:0},limits:{bus:3,rail:0,air:0},corridors:{},spawnDay:16,spawnClock:0,saveClock:0,hubCount:0,unlocked:['bus'],rewardDue:0,periods:0,seed:Math.random(),ledger:{fares:0,tasks:0,subsidy:0,construction:0,vehicles:0},history:[],lastSettlement:0};}

function regionStrength(x,y){return Math.max(Math.exp(-((x-350)**2+(y-325)**2)/65000),Math.exp(-((x-875)**2+(y-350)**2)/45000));}
function makeCity(x,y,size=0,shape=0,color=0){return {growth:0,served:0,stage:size,potential:1,maxSize:2,id:S.cities.length,x,y,size,shape,color,name:names[S.cities.length%names.length],q:[],capacity:[24,40,64][size],expand:0,hub:false,shield:0,grace:30,warning:0,dormant:false,activatedDay:S.day,mission:{step:0,progress:0,completed:0},arrivals:0,departures:0};}

function reset(){vehicleVisuals.clear();hideJunction();stopUndo=null;S=fresh();S.cities=[makeCity(245,330,0,1,0)];S.cities.push(makeCity(405,265,0,0,1));S.cities.push(makeCity(445,425,0,2,2));['湖湾镇','林溪镇','河岸镇'].forEach((n,i)=>S.cities[i].name=n);selected=null;draft=null;fit();updateUI();}

function save(){try{localStorage.setItem('transit-atlas-city-beta-v1',JSON.stringify(S))}catch{}}
function load(){try{const x=JSON.parse(localStorage.getItem('transit-atlas-city-beta-v1'));if(x&&x.version===1&&x.economyVersion===3){S=x;S.paused=true;return true}}catch{}return false}

function toast(t){$('toast').classList.remove('undo-enabled');$('toast').textContent=t;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3500)}
function resize(){W=innerWidth;H=innerHeight;portraitMode=H>W;view.rot=0;syncOrientation();dpr=devicePixelRatio||1;cv.width=W*dpr;cv.height=H*dpr;fit()}
function fit(){let usableH=H-130;view.scale=Math.min((W-65)/1200,usableH/710);view.x=(W-1200*view.scale)/2;view.y=75+(usableH-710*view.scale)/2;}
function toWorld(e){let u=(e.clientX-view.x)/view.scale,v=(e.clientY-view.y)/view.scale;return view.rot?{x:v,y:-u}:{x:u,y:v}}
// Portrait rotation: screen = (view.x - y*scale, view.y + x*scale). Art and labels stay upright via the helpers below.
function toScreen(p){return view.rot?{x:view.x-p.y*view.scale,y:view.y+p.x*view.scale}:{x:view.x+p.x*view.scale,y:view.y+p.y*view.scale}}
// Upright compensation exists only to undo the portrait map rotation. Objects drawn in their own heading frame
// (vehicles, carriages) run inside a local scope and are never "turned upright": body, windows, wheels and cars
// all follow the line. Landscape has no map rotation, so nothing is ever compensated there.
let localFrameDepth=0;
function ctxRotated(){if(!view.rot||localFrameDepth>0)return false;let m=ctx.getTransform?.();return !!m&&Math.abs(m.b)>Math.abs(m.a)+1e-6}
function uprightHere(){if(ctxRotated())ctx.rotate(-Math.PI/2)}
function uprightAround(x,y){if(ctxRotated()){ctx.translate(x,y);ctx.rotate(-Math.PI/2);ctx.translate(-x,-y)}}
function radius(c){return 12+c.size*2;}
function hitCity(p){let best=null,dist=Infinity;for(const c of S.cities){let d=Math.hypot(c.x-p.x,c.y-p.y);if(d<Math.max(radius(c)+10,(globalThis.HIT_PX||21)/view.scale)&&d<dist){best=c;dist=d}}return best}
function terrainRadius(a,e){return 1+.075*Math.sin(a*5+e.x*.01)+.055*Math.cos(a*9+e.y*.02)+.035*Math.sin(a*13);}
function inEllipse(p,e){let x=(p.x-e.x)/e.rx,y=(p.y-e.y)/e.ry;return Math.hypot(x,y)<terrainRadius(Math.atan2(y,x),e)}
function segDist(p,a,b){const dx=b.x-a.x,dy=b.y-a.y,t=Math.max(0,Math.min(1,((p.x-a.x)*dx+(p.y-a.y)*dy)/(dx*dx+dy*dy||1)));return Math.hypot(p.x-a.x-dx*t,p.y-a.y-dy*t)}
const mountainPolygons=mountains.map(e=>Array.from({length:160},(_,i)=>{let a=i/160*Math.PI*2,r=terrainRadius(a,e);return {x:e.x+Math.cos(a)*e.rx*r,y:e.y+Math.sin(a)*e.ry*r};}));
function pointInPolygon(p,poly){let inside=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++){let a=poly[i],b=poly[j];if((a.y>p.y)!==(b.y>p.y)&&p.x<(b.x-a.x)*(p.y-a.y)/(b.y-a.y)+a.x)inside=!inside;}return inside;}
// The river valley is a physical gap in the mountain, not water painted over rock.
const RIVER_VALLEY_HALF_WIDTH=32;
const riverValleyBanks=[-1,1].map(side=>Array.from({length:435},(_,i)=>{let y=-300+i*3;return {x:river(y)+side*RIVER_VALLEY_HALF_WIDTH,y};}));
function valleyCenter(y){let lo=Math.floor((y+300)/3),t=(y+300)/3-lo;if(lo<0||lo>=434)return river(y);return riverValleyBanks[0][lo].x*(1-t)+riverValleyBanks[0][lo+1].x*t+RIVER_VALLEY_HALF_WIDTH;}
function inRiverValley(p){return Math.abs(p.x-valleyCenter(p.y))<RIVER_VALLEY_HALF_WIDTH;}
function clipMountainValley(){ctx.beginPath();ctx.rect(-300,-300,2000,1400);let left=riverValleyBanks[0],right=riverValleyBanks[1];ctx.moveTo(left[0].x,left[0].y);for(let p of left)ctx.lineTo(p.x,p.y);for(let p of right.slice().reverse())ctx.lineTo(p.x,p.y);ctx.closePath();ctx.clip('evenodd');}
function mountainDistance(p){let best=Infinity;for(let poly of mountainPolygons){if(pointInPolygon(p,poly))return 0;for(let i=0;i<poly.length;i++)best=Math.min(best,segDist(p,poly[i],poly[(i+1)%poly.length]));}return best;}
function cityBuildable(x,y,size=0){let clearance=[12,17,23][size]+32;return x<coast(y)-clearance&&Math.abs(x-river(y))>clearance+9&&mountainDistance({x,y})>clearance;}
const crossingCache=new Map();
function mountainCrossings(a,b){let cacheKey=[a.x,a.y,b.x,b.y].join(',');if(crossingCache.has(cacheKey))return crossingCache.get(cacheKey);let dx=b.x-a.x,dy=b.y-a.y,cuts=[0,1];
for(let poly of mountainPolygons)for(let i=0;i<poly.length;i++){let p=poly[i],q=poly[(i+1)%poly.length],ex=q.x-p.x,ey=q.y-p.y,den=dx*ey-dy*ex;if(Math.abs(den)<1e-9)continue;let t=((p.x-a.x)*ey-(p.y-a.y)*ex)/den,u=((p.x-a.x)*dy-(p.y-a.y)*dx)/den;if(t>0&&t<1&&u>=0&&u<=1)cuts.push(t);}
// Intersect the exact same sampled valley edges used by the background clip.
for(let bank of riverValleyBanks)for(let i=1;i<bank.length;i++){let p=bank[i-1],q=bank[i],ex=q.x-p.x,ey=q.y-p.y,den=dx*ey-dy*ex;if(Math.abs(den)<1e-9)continue;let t=((p.x-a.x)*ey-(p.y-a.y)*ex)/den,u=((p.x-a.x)*dy-(p.y-a.y)*dx)/den;if(t>0&&t<1&&u>=0&&u<=1)cuts.push(t);}
cuts.sort((x,y)=>x-y);let spans=[];for(let i=1;i<cuts.length;i++){let lo=cuts[i-1],hi=cuts[i];if(hi-lo<1e-7)continue;let t=(lo+hi)/2,p={x:a.x+dx*t,y:a.y+dy*t};if(!inRiverValley(p)&&mountainPolygons.some(poly=>pointInPolygon(p,poly))){if(spans.length&&Math.abs(spans.at(-1)[1]-lo)<1e-6)spans.at(-1)[1]=hi;else spans.push([lo,hi]);}}
if(crossingCache.size>2500)crossingCache.clear();crossingCache.set(cacheKey,spans);return spans;}
function requirements(a,b,type){if(type==='air')return {bridge:0,tunnel:0,hill:0};let bridge=0,hill=0,lastR=false;for(let i=0;i<=80;i++){let t=i/80,p={x:a.x+(b.x-a.x)*t,y:a.y+(b.y-a.y)*t};if(p.x>coast(p.y)-4)return {invalid:'线路不能经过海域'};let r=Math.abs(p.x-river(p.y))<9;if(r&&!lastR)bridge++;if(hills.some(e=>inEllipse(p,e)))hill++;lastR=r;}return {bridge,tunnel:mountainCrossings(a,b).length,hill:hill/81};}

function key(a,b,type){return [type,...[a.id,b.id].sort((x,y)=>x-y)].join('-')}
function edgeTime(a,b,type){let r=requirements(a,b,type);return Math.hypot(a.x-b.x,a.y-b.y)/TYPES[type].speed*(1+(r.hill||0)*.65)}
function plan(start,p){let n=S.cities.length,dist=Array(n).fill(Infinity),first=Array(n).fill(null),prevType=Array(n).fill(null),done=new Set();dist[start]=0;let target=null;for(let k=0;k<n;k++){let u=-1;for(let i=0;i<n;i++)if(!done.has(i)&&(u<0||dist[i]<dist[u]))u=i;if(u<0||!isFinite(dist[u]))break;done.add(u);let city=S.cities[u];if(u!==start&&(matchesDestination(city,p))){target=u;break}for(const l of S.lines){let vs=S.vehicles.filter(v=>v.line===l.id);if(!vs.length||l.retiring)continue;let idx=l.stops.indexOf(u);if(idx<0)continue;let total=0;for(let j=1;j<l.stops.length;j++)total+=edgeTime(S.cities[l.stops[j-1]],S.cities[l.stops[j]],l.type)+1;let freq=total*2/vs.length,capacity=vs.reduce((s,v)=>s+vehCap(v),0)/vs.length;for(let ni of [idx-1,idx+1]){if(ni<0||ni>=l.stops.length)continue;let v=l.stops[ni],transfer=prevType[u]===l.id?0:TYPES[l.type].transfer+Math.min(freq/2,25)+city.q.length/Math.max(capacity,1)*Math.min(freq,25);let nd=dist[u]+edgeTime(city,S.cities[v],l.type)+transfer;if(nd<dist[v]){dist[v]=nd;first[v]=first[u]||{line:l.id,next:v};prevType[v]=l.id}}}}return target===null?null:{...first[target],target,time:dist[target]}}
function vehCap(v){return isTrain(v.type)?v.cars*TYPES[v.type].cap:TYPES[v.type].cap}
function newPassenger(c){let choices=S.cities.filter(d=>d.id!==c.id&&!d.dormant);if(!choices.length)return;let weights=choices.map(d=>Math.pow(1.45,d.stage??d.size)*(c.shape===0?(d.shape===2||d.shape===3?2.6:1):d.shape===1?1.9:d.shape===2?1.4:1));let roll=Math.random()*weights.reduce((a,b)=>a+b,0),dest=choices[0];for(let i=0;i<choices.length;i++){roll-=weights[i];if(roll<=0){dest=choices[i];break}}let distance=Math.hypot(c.x-dest.x,c.y-dest.y);c.q.push({id:S.nextP++,origin:c.id,dest:dest.id,fare:distance<250?1:distance<500?2:3,color:dest.color,shape:dest.shape,wait:0,ready:0});}

function isHoliday(){return false;}

function spawnCity(){if(S.cities.length>=24||S.cities.filter(c=>c.dormant).length>=2)return;for(let tries=0;tries<250;tries++){let progress=Math.min(S.day/100,1),x=rand(100,Math.min(960,500+progress*550)),y=rand(255,620);if(!cityBuildable(x,y)||S.cities.some(c=>Math.hypot(c.x-x,c.y-y)<115))continue;let shape=Math.floor(rand(0,4)),color=S.cities.length%3,c=makeCity(x,y,0,shape,color);c.dormant=true;c.grace=45;S.cities.push(c);toast('发现 '+c.name+' · 待接入，暂不产生候车压力');return;}}

function arrival(v,l){let city=S.cities[l.stops[v.index]],keep=[];let live=S.lines.find(x=>x.id===v.line);if(v.stops&&live.stops.includes(city.id)){v.index=live.stops.indexOf(city.id);v.stops=null;l=live;}if(live.retiring||v.recall){for(let p of v.people){p.ready=2;city.q.push(p)}v.people=[];v.retired=true;S.inventory[v.type]++;return;}for(let p of v.people){if(matchesDestination(city,p)){S.delivered++;S.periodDelivered++;city.served=(city.served||0)+1;completeTrip(p,city);continue}let next=plan(city.id,p),nextIdx=v.index+v.dir;if(next&&next.line===l.id&&nextIdx>=0&&nextIdx<l.stops.length&&next.next===l.stops[nextIdx]){keep.push(p)}else{let onward=next?S.lines.find(x=>x.id===next.line):null;p.ready=onward?TYPES[onward.type].transfer:1.5;city.q.push(p)}}v.people=keep;let nextIdx=v.index+v.dir;if(nextIdx<0||nextIdx>=l.stops.length){v.dir*=-1;nextIdx=v.index+v.dir}const next=l.stops[nextIdx];let remain=[];city.q.sort((a,b)=>b.wait-a.wait);for(let p of city.q){if(p.ready>0||v.people.length>=vehCap(v)){remain.push(p);continue}let route=plan(city.id,p);if(route&&route.line===l.id&&route.next===next){v.people.push(p);city.served=(city.served||0)+1;}else remain.push(p)}city.q=remain;v.dwell=l.type==='air'?4:isTrain(l.type)?1.7:1;v.dwellMax=v.dwell;}
function tick(dt){const oldDay=Math.floor(S.day);S.day+=dt/12;updateWorld(dt,oldDay);S.spawnClock+=dt;for(let c of S.cities){if(c.dormant)continue;c.grace=Math.max(0,c.grace-dt);c.shield=Math.max(0,c.shield-dt);let max=0;for(let p of c.q){p.journey=(p.journey||0)+dt;p.ready=Math.max(0,p.ready-dt);if(c.grace<=0&&p.ready<=0)p.wait+=dt*(c.q.length>capacity(c)?1.7:1)*(c.hub?.65:1);if(!p.eventId)max=Math.max(max,p.wait)}if(c.shield<=0&&max>=180){if(c.warning<=0)c.warning=8;else c.warning-=dt;if(c.warning<=0){S.lives--;c.shield=45;c.warning=0;toast(c.name+'旅客等待超时 · 扣除一条生命，保护45秒');if(S.lives<=0){S.paused=true;gameover();return}}}else c.warning=0}
for(let c of S.cities){if(c.dormant)continue;if(c.stage===undefined)c.stage=c.size;c.stage=Math.min(c.size,c.stage+dt/120);if(c.grace>0)continue;let expected=passengerRate(c)*dt,count=Math.floor(expected)+(Math.random()<expected%1?1:0);for(let i=0;i<count;i++)newPassenger(c);}

for(let v of S.vehicles){for(let p of v.people)p.journey=(p.journey||0)+dt;let base=S.lines.find(l=>l.id===v.line);let l=v.stops?{...base,stops:v.stops}:base;if(!l||l.stops.length<2||v.retired)continue;if(v.dwell>0){v.dwell-=dt;continue}let next=v.index+v.dir;if(next<0||next>=l.stops.length){v.dir*=-1;next=v.index+v.dir}let a=S.cities[l.stops[v.index]],b=S.cities[l.stops[next]];v.t+=dt/Math.max(.5,edgeTime(a,b,l.type));if(v.t>=1){for(let p of v.people)recordSegment(p,a,b,l.type);let pa=lanePoint(a,b,l,.994),pb=lanePoint(a,b,l,1);v.incomingAngle=Math.atan2(pb.y-pa.y,pb.x-pa.x);v.t=0;v.index=next;arrival(v,l)}}
S.vehicles=S.vehicles.filter(v=>!v.retired);S.lines=S.lines.filter(l=>!l.retiring||S.vehicles.some(v=>v.line===l.id));
if(S.day>=S.spawnDay){spawnCity();S.spawnDay+=16}
if(Math.floor(S.day/10)>S.periods){S.periods=Math.floor(S.day/10);credit(1000,'subsidy','十天基础补助');S.periodDelivered=0;reward(1000)}
S.saveClock+=dt;if(S.saveClock>10){S.saveClock=0;save()} }
function passengerRate(c){if(c.dormant)return 0;let ramp=Math.min(1,.3+Math.max(0,S.day-c.activatedDay)/5);return .07*Math.pow(1.5,c.stage??c.size)*ramp;}

function settleCityGrowth(){/* Growth is awarded by city transport tasks. */}

function minScale(){return Math.min(.35,fitTarget().scale)}
function syncOrientation(){let hint=$('orientation-hint');if(!hint)return;hint.hidden=!portraitMode||orientationHintDismissed;if(!hint.hidden&&!syncOrientation.t)syncOrientation.t=setTimeout(()=>{orientationHintDismissed=true;try{localStorage.setItem('transit04-hint-off','1')}catch{}syncOrientation()},9000);}
async function enterLandscape(){let info=$('orientation-status');try{if(!document.fullscreenElement&&document.documentElement?.requestFullscreen)await document.documentElement.requestFullscreen();if(typeof screen!=='undefined'&&screen.orientation?.lock)await screen.orientation.lock('landscape');}catch{}resize();if(portraitMode&&info)info.textContent='也可继续竖屏游玩；想横屏时，请开启手机自动旋转。';}
function capacity(c){return Math.round(c.capacity*(1+c.expand*.25)*(c.hub?2:1))}
function pathShape(x,y,r,shape){ctx.beginPath();if(shape===0)ctx.arc(x,y,r,0,Math.PI*2);if(shape===1){ctx.moveTo(x,y-r*1.1);ctx.lineTo(x+r,y+r*.8);ctx.lineTo(x-r,y+r*.8);ctx.closePath()}if(shape===2){ctx.moveTo(x,y-r*1.15);ctx.lineTo(x+r,y);ctx.lineTo(x,y+r*1.15);ctx.lineTo(x-r,y);ctx.closePath()}if(shape===3)ctx.rect(x-r*.85,y-r*.85,r*1.7,r*1.7)}
function text(t,x,y,size=12,color='#8e9a90',align='center'){ctx.fillStyle=color;ctx.font=`${size}px "Noto Sans SC",system-ui,sans-serif`;ctx.textAlign=align;if(ctxRotated()){ctx.save();ctx.translate(x,y);ctx.rotate(-Math.PI/2);textInk(t,0,0,size);ctx.restore()}else textInk(t,x,y,size)}
function textInk(t,x,y,size){if(globalThis.TEXT_HALO&&globalThis.uxHaloOK!==false&&ctx.canvas===cv){ctx.save();ctx.lineJoin='round';ctx.lineWidth=Math.max(2,size*.34);ctx.strokeStyle=globalThis.TEXT_HALO;ctx.strokeText(t,x,y);ctx.restore()}ctx.fillText(t,x,y)}
function ellipse(e,fill,stroke){ctx.beginPath();ctx.ellipse(e.x,e.y,e.rx,e.ry,0,0,Math.PI*2);ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.stroke()}}
let terrainCache=null;
function contourPath(e,f=1,dx=0,dy=0){ctx.beginPath();for(let i=0;i<=160;i++){let a=i/160*Math.PI*2,r=terrainRadius(a,e)*f,x=e.x+Math.cos(a)*e.rx*r+dx,y=e.y+Math.sin(a)*e.ry*r+dy;if(!i)ctx.moveTo(x,y);else ctx.lineTo(x,y)}ctx.closePath();}
function coastPath(shift=0){ctx.beginPath();for(let y=-300;y<=1100;y+=3){let x=coast(y)+shift;if(y===-300)ctx.moveTo(x,y);else ctx.lineTo(x,y)}}
function riverPath(){ctx.beginPath();for(let y=-300;y<=1100;y+=3){let x=river(y);if(y===-300)ctx.moveTo(x,y);else ctx.lineTo(x,y)}}
// Cartographic background only: every physical boundary stays tied to game geometry.
function terrainStroke(points,color,width=1){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.strokeStyle=color;ctx.lineWidth=width;ctx.stroke();}
