function frame(now){let dt=Math.min(.08,(now-last)/1000);last=now;if(!S.paused&&!modalOpen&&!draft&&!bridgeDraft&&S.lives>0)tick(dt*S.speed);detailClock+=dt;if(detailClock>.5){detailClock=0;updateUI();if(selected&&!draft)showDetails(false)}render()}
function formatDate(){let d=Math.floor(S.day),year=Math.floor(d/360)+1,month=Math.floor(d%360/30)+1,day=d%30+1;return {d,year,month,day,weekday:['周一','周二','周三','周四','周五','周六','周日'][d%7]}}
function updateUI(){const d=formatDate();$('year').textContent=`第${d.year}年`;$('date').innerHTML=`${d.month}月${d.day}日 <span>${d.weekday}</span>`;$('calendar-tag').textContent=`${isHoliday()?'节假日 · ':d.d%7>=5?'周末 · ':''}距补助${Math.max(1,10-d.d%10)}天`;$('points').textContent='¥'+S.points;$('delivered').textContent=S.delivered;$('lives').textContent='♥ '.repeat(S.lives)+'♡ '.repeat(2-S.lives);$('pause').textContent=S.paused?'▶':'Ⅱ';$('pause').classList?.toggle?.('is-paused',!!S.paused);$('pause').title=S.paused?'继续':'暂停';$('speed').textContent=S.speed+'×';$('routecount').textContent=S.lines.length+' 条线路';$('stock').textContent=`任务已完成 ${S.cities.reduce((n,c)=>n+c.mission.completed,0)} · 已繁荣 ${S.cities.filter(c=>c.size>0).length}城`;$('next-supply').textContent=`${Math.max(1,10-d.d%10)}天后补助`;$('notice').textContent=S.day<3?'城市成长测试版 · 点击城市查看任务 · 新线确认报价后建设':S.cities.some(c=>c.dormant)?'发现新城 · 30秒后自动开放，最后10秒提醒':'';
$('route-list').innerHTML=S.lines.map(l=>`<div class="route-row ${selected?.type==='line'&&selected.id===l.id?'active':''}" data-line="${l.id}"><span class="swatch" style="border-color:${l.color};border-top-style:${l.type==='air'?'dashed':'solid'};${isTrain(l.type)?'border-top-style:double;border-top-width:5px':''}"></span><span class="name">${escapeHTML(l.name)}</span><small>${TYPES[l.type].short} · ${S.vehicles.filter(v=>v.line===l.id).length}</small></div>`).join('');}
function escapeHTML(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function openModal(html){modalOpen=true;$('modal-content').innerHTML=html;$('modal').hidden=false}
function closeModal(){modalOpen=false;$('modal').hidden=true;save()}
function welcome(hasSave){openModal(`<span class="eyebrow">CITY & ECONOMY / 城市成长测试版 0.1</span><h1>从一条线，带动一座城。</h1><p>沿用原来的拉线玩法与2D车辆。完成城市任务，领奖金、看小镇成长，再决定下一笔建设。</p><div class="intro-grid"><div class="intro-card"><span>¥500</span><b>起步资金，精打细算</b><small>公交180；拉线另计建设费。首辆车自动加入报价，已有车辆可调配。</small></div><div class="intro-card"><span>↗</span><b>任务推动城市繁荣</b><small>点击城市查看任务。实际送达或完成通勤后计数，奖金自动到账。</small></div><div class="intro-card"><span>10日</span><b>低客流，慢慢经营</b><small>十天补助100，没有免费车辆。新城待接入，连通后再逐渐增加客流。</small></div></div><button class="primary" onclick="startGame()">${hasSave?'继续测试':'开始测试'} →</button>${hasSave?'<button onclick="newGame()" style="margin-left:15px">重新测试</button>':''}<p style="font-size:10px">独立测试存档，不影响正式版。资金不足不会停运；旅客等待超时仍会损失生命。<br>每个游戏日12秒，可暂停、调速。<a href="../">返回正式版</a></p>`);}

function startGame(){closeModal();S.paused=false;fit();toast(S.lines.length?'点击城市查看任务；点击线路配车':'从湖湾镇拖到林溪镇，再接河岸镇；查看报价确认建设');updateUI();}

function newGame(){reset();closeModal();S.paused=false;save()}
function gameover(){save();openModal(`<span class="eyebrow">旅程结算</span><h1>东岸，感谢你的连接。</h1><p>网络坚持了 ${Math.floor(S.day)} 天，共送达 ${S.delivered} 位旅客。<br>试试更均匀的班次，或为繁忙线路增加车辆。</p><button class="primary" onclick="newGame()">重新规划 →</button>`)}
function chooseType(){openModal(`<div class="modal-head"><h2>新建线路</h2><button class="close" onclick="closeModal()">×</button></div><p>选择方式，再拖动连接城市。松手保留规划，查看报价后建设。初期公交每100地图单位约380资金。</p><div class="reward-grid">${Object.entries(TYPES).map(([t,v])=>`<button class="reward" onclick="beginDraft('${t}')" ${!S.unlocked.includes(t)||S.lines.filter(l=>l.type===t&&!l.retiring).length>=S.limits[t]?'disabled':''}>${transportIcon(t)}<b>${v.name}</b><small>${S.unlocked.includes(t)?'首辆 ¥'+v.vehicle+' · 库存 '+S.inventory[t]:'第'+(isTrain(t)?30:60)+'天开放'}</small></button>`).join('')}</div><p>公交最多3条；第30天开放高铁，第60天开放航空。载具需自行购买。</p>`);}

function beginDraft(type,existing=null){hideJunction();closeModal();let l=existing?S.lines.find(l=>l.id===existing):null;draft=l?{...l,stops:[...l.stops],original:l.id}:{id:S.nextL,type,name:TYPES[type].name+(S.lines.filter(l=>l.type===type).length+1)+'线',color:LINECOL[S.lines.length%LINECOL.length],stops:[]};selected=null;$('details').hidden=true;draftBar();}
function draftBar(){if(!draft){$('drawbar').hidden=true;return}let cost=draftCost();$('drawbar').hidden=false;$('drawtext').textContent=`${draft.name} · ${draft.stops.length}站 · 建设 ¥${cost.cash}${cost.vehicle?'（含首辆车）':''}${cost.bridge?' · 桥×'+cost.bridge:''}${cost.tunnel?' · 隧道×'+cost.tunnel:''}${cost.invalid?' · '+cost.invalid:''}${cost.cash>S.points?' · 资金不足':''}`;$('drawdone').textContent=cost.cash?'查看报价':'应用修改';$('drawdone').disabled=draft.stops.length<2||!!cost.invalid||cost.cash>S.points;}

function draftCost(){let cost={bridge:0,tunnel:0,cash:0,works:0,vehicle:0,length:0};if(!draft)return cost;let seen=new Set();for(let i=1;i<draft.stops.length;i++){let a=S.cities[draft.stops[i-1]],b=S.cities[draft.stops[i]],r=requirements(a,b,draft.type),k=key(a,b,draft.type);if(r.invalid)cost.invalid=r.invalid;if(!S.corridors[k]&&!seen.has(k)){seen.add(k);cost.bridge+=r.bridge;cost.tunnel+=r.tunnel;let length=Math.hypot(a.x-b.x,a.y-b.y);cost.length+=length;if(!draft.stopRemoval)cost.cash+=10*Math.ceil(length*({bus:.38,emu:.65,rail:1.1,air:.18}[draft.type]));}}cost.works=Math.max(0,cost.bridge-S.inventory.bridge)*1500+Math.max(0,cost.tunnel-S.inventory.tunnel)*2200;if(!draft.original&&!S.inventory[draft.type])cost.vehicle=TYPES[draft.type].vehicle;cost.cash+=cost.works+cost.vehicle;return cost;}

function commitDraft(skipCostConfirmation=false){if(!draft||draft.stops.length<2)return;let removal=draft.stopRemoval,cost=draftCost();if(cost.invalid)return toast(cost.invalid);if(cost.cash>S.points)return toast('资金不足：需要 ¥'+cost.cash+'，现有 ¥'+S.points);if((cost.cash||cost.bridge||cost.tunnel)&&skipCostConfirmation!==true){showConstructionConfirmation(cost);return;}spend(cost.cash-cost.vehicle,'construction','线路与工程建设');if(cost.vehicle){spend(cost.vehicle,'vehicles','首辆载具');S.inventory[draft.type]++;addStockAsset(draft.type,{cars:isTrain(draft.type)?2:1,investment:cost.vehicle});}S.inventory.bridge=Math.max(0,S.inventory.bridge-cost.bridge);S.inventory.tunnel=Math.max(0,S.inventory.tunnel-cost.tunnel);for(let i=1;i<draft.stops.length;i++){let a=S.cities[draft.stops[i-1]],b=S.cities[draft.stops[i]];S.corridors[key(a,b,draft.type)]=true;}for(let id of draft.stops){let c=S.cities[id];if(c.kind==='bridgehead')continue;if(c.dormant)activateDiscoveredCity(c,false);}let id;if(draft.original){id=draft.original;let l=S.lines.find(l=>l.id===id);for(let v of S.vehicles.filter(v=>v.line===id))unloadForEdit(v,l);l.stops=[...draft.stops];l.manualBridges=true;}else{id=S.nextL++;S.lines.push({id,type:draft.type,name:draft.name,color:draft.color,stops:[...draft.stops],manualBridges:true});if(S.inventory[draft.type])addVehicle(id,false);}draft=null;$('drawbar').hidden=true;selected={type:'line',id};showDetails();updateUI();save();if(removal&&!cost.cash)offerStopUndo(id,removal);else toast('线路已应用 · '+(cost.cash?'支出 ¥'+cost.cash:'使用已有通道，无建设费'));}

function showConstructionConfirmation(cost){openModal(`<div class="modal-head"><h2>建设报价</h2><button class="close" onclick="closeModal()">×</button></div><p>${escapeHTML(draft.name)} · ${draft.stops.map(id=>escapeHTML(S.cities[id].name)).join(' → ')}</p><div class="quote-row"><span>新增线路</span><b>¥${cost.cash-cost.works-cost.vehicle}</b></div><div class="quote-row"><span>桥梁 ${cost.bridge} / 隧道 ${cost.tunnel}</span><b>¥${cost.works}</b></div><div class="quote-row"><span>${draft.original?'保留现有车辆':'首辆'+TYPES[draft.type].name}${cost.vehicle?' · 自动购入':draft.original?'':' · 使用库存'}</span><b>¥${cost.vehicle}</b></div><div class="quote-row total"><span>合计 / 建成后余额</span><b>¥${cost.cash} / ¥${S.points-cost.cash}</b></div><p>按新增路段计费，已建通道不重复收费。车辆保持2D自动往返运行。</p><div class="construction-actions"><button onclick="closeModal()">返回调整</button><button class="primary" id="construction-confirm" onclick="confirmConstruction()">确认建设 ¥${cost.cash}</button></div>`);}

function confirmConstruction(){if(!draft){closeModal();return;}closeModal();commitDraft(true);}
function unloadForEdit(v,l){if(!v.stops)v.stops=[...l.stops];}
function addVehicle(id,notify=true){let l=S.lines.find(l=>l.id===id);if(!l||S.inventory[l.type]<=0){if(notify)toast('没有可用载具，请先在商店购买');return}let asset=takeStockAsset(l.type);S.inventory[l.type]--;let vs=S.vehicles.filter(v=>v.line===id),idx=vs.length?Math.floor(l.stops.length/2):0;S.vehicles.push({id:S.nextV++,line:id,type:l.type,index:Math.min(idx,l.stops.length-1),dir:idx? -1:1,t:0,dwell:vs.length?3:0,people:[],cars:asset.cars,investment:asset.investment,legacyInvestment:asset.legacyInvestment||false});if(notify){toast('已增加一辆'+TYPES[l.type].name);showDetails();save()}}
function removeVehicle(id){let v=S.vehicles.find(v=>v.id===id),l=S.lines.find(l=>l.id===v.line);if(v.people.length){v.recall=true;return toast('已安排回收，将在下一站卸客')}retireVehicleAsset(v);S.vehicles=S.vehicles.filter(v=>v.id!==id);showDetails();save()}
function upgradeCar(id){let v=S.vehicles.find(v=>v.id===id);if(!v||v.type!=='rail'||v.cars>=8)return;let price=v.cars<4?40:v.cars<6?55:70;if(S.points<price)return toast('资金不足');spend(price,'vehicles','增加车厢');v.cars++;showDetails();save();toast('车厢升级至 '+v.cars+'/8 节')}
function activateLineEdit(id){selectLine(id);toast('抓住城市旁的线段，拖过城市摘下或挂上；松手生效');}
function selectLine(id){hideJunction();selected={type:'line',id};showDetails();updateUI()}
function showDetails(rebuild=true){if(selected?.type==='junction'){$('details').hidden=true;return;}if(!rebuild){let c=selected&&S.cities[selected.id];let sig=JSON.stringify({mission:c?.mission,sel:selected,points:S.points,lines:S.lines.map(l=>[l.id,l.name,l.stops,l.retiring]),v:S.vehicles.map(v=>[v.id,v.cars,v.people.length]),city:selected?.type==='city'||selected?.type==='stop'?[c?.size,c?.growth,c?.q.length,c?.q.map(p=>[p.color,p.shape,Math.floor(p.wait)])]:null,inv:S.inventory});if(sig===lastPanelSignature)return;lastPanelSignature=sig;}if(selected?.type==='vehicle')return showVehicleDetails();let el=$('details');if(!selected){el.hidden=true;return}if(el.contains(document.activeElement)&&document.activeElement.tagName==='INPUT')return;el.hidden=false;if(selected.type==='line'){let l=S.lines.find(l=>l.id===selected.id);if(!l){selected=null;el.hidden=true;return}let vs=S.vehicles.filter(v=>v.line===l.id);el.innerHTML=`<button class="close" onclick="clearSelection()">×</button><h3>${escapeHTML(l.name)}</h3><div class="detail-sub">${TYPES[l.type].name} · ${(typeof isLoop130==='function'?isLoop130:()=>false)(l)?'公交环线':'终点折返'}</div><div class="metric-grid"><div><small>停靠城市</small><b>${l.stops.length}</b></div><div><small>载具 / 总座位</small><b>${vs.length} <small>/ ${vs.reduce((n,v)=>n+vehCap(v),0)}</small></b></div></div><div class="detail-actions"><button onclick="addVehicle(${l.id})">库存加车 (${S.inventory[l.type]})</button><button onclick="buyAndAdd(${l.id})">购买并加车 ¥${TYPES[l.type].vehicle}</button><button onclick="activateLineEdit(${l.id})">拖动改线</button><button onclick="renameLine(${l.id})">名称 / 颜色</button><button onclick="deleteLine(${l.id})">撤销整条线路</button></div><div class="stop-list"><p class="detail-sub">途经城市与桥头 · 桥头不停车</p>${l.stops.filter(id=>!S.cities[id].removed).map((id,index)=>`<div class="stop-list-row"><span><small>${index+1}</small> ${escapeHTML(S.cities[id].name)}</span><button onclick="prepareRemoveStop(${l.id},${id})" aria-label="移除${escapeHTML(S.cities[id].name)}这一站">移除此站</button></div>`).join('')}</div>${vs.map(v=>`<div class="vehicle-row"><span>${TYPES[v.type].name} #${v.id}　${v.people.length}/${vehCap(v)}人 <b class="${v.people.length>=vehCap(v)?'danger':''}">${v.people.length>=vehCap(v)?'满员':v.people.length/vehCap(v)>=.8?'接近满员':''}</b> ${isTrain(v.type)?v.cars+'/8节':''}</span>${isTrain(v.type)&&v.cars<8?`<button onclick="upgradeCar(${v.id})">＋车厢 ¥${carPrice(v)}</button>`:`<button onclick="removeVehicle(${v.id})">回收</button>`}</div>`).join('')}${!vs.length?'<p class="danger">未投入载具，旅客不会使用这条线路。</p>':''}`;}else{let c=S.cities[selected.id];if(!c)return;let groups={};for(let p of c.q){let k=p.schoolId!==undefined?'s:'+p.dest+':'+p.schoolReturn:(p.eventId||p.cardId||p.fixedDestination)?(typeof specialPassengerMark130==='function'?specialPassengerMark130(p):'')+':'+p.dest:p.color+'-'+p.shape+':r'+(p.destRegion??'any');(groups[k]??=[]).push(p)}let max=Math.max(0,...c.q.map(p=>p.wait));el.innerHTML=`<button class="close" onclick="clearSelection()">×</button><h3>${c.name}${c.hub?' · 枢纽':''}</h3><div class="detail-sub">${['小','中','大'][c.size]}型 · ${['居住城市','旅游城市','商业城市','工业城市'][c.shape]}</div><div class="metric-grid"><div><small>候车 / 容量</small><b>${c.q.length} <small>/ ${capacity(c)}</small></b></div><div><small>满员压力</small><b>${Math.ceil(c.congestionPressure||0)}<small> / ${c.shape===1?225:180}秒</small></b></div></div><div class="bar"><i style="width:${Math.min(100,(c.congestionPressure||0)/(c.shape===1?225:180)*100)}%"></i></div>${selected.type==='stop'?`<div class="stop-edit"><b>${escapeHTML(S.lines.find(l=>l.id===selected.line)?.name||'线路')} · 当前停靠</b><button onclick="prepareRemoveStop(${selected.line},${c.id})">从本线路移除</button></div>`:''}<p class="growth-caption">${c.size>=c.maxSize?'已成为繁荣城市':'完成交通任务推动繁荣 · 每两项任务升级'}${(c.stage??c.size)<c.size?' · 客流适应中':''}</p>${missionHTML(c)}<p class="detail-sub" style="margin:12px 0 4px">候车目的地 · 点击查看匹配城市</p>${Object.entries(groups).map(([k,ps])=>{let p=ps[0];return `<button class="passenger-row destination-row" onclick="focusPassenger('${(typeof specialPassengerMark130==='function'?specialPassengerMark130(p):'')?'event':'normal'}',${p.dest??-1},${p.color},${p.shape},${p.destRegion??'null'})"><span style="color:${COLORS[p.color]}">${passengerLabel(p)}</span><span>${ps.length}人 · ${Math.floor(Math.max(...ps.map(p=>p.wait)))}s</span></button>`}).join('')||'<p class="detail-sub">暂时没有旅客等待。</p>'}`}}
function prepareRemoveStop(lineId,cityId){let l=S.lines.find(l=>l.id===lineId);if(!l||l.retiring)return;if(l.stops.length<=2)return toast('一条线路至少连接两座城市；请使用撤线删除整条线路。');beginDraft(l.type,lineId);draft.stopRemoval={before:[...l.stops],name:S.cities[cityId].name};draft.stops=draft.stops.filter(id=>id!==cityId);draftBar();let cost=draftCost(),invalid=cost.invalid||cost.cash>S.points;if(!invalid&&!cost.cash&&!cost.bridge&&!cost.tunnel){commitDraft();return;}openModal(`<h2>移除这一个停靠点？</h2><p>只移除${escapeHTML(l.name)}对${S.cities[cityId].name}的停靠，城市及其他线路保留。</p><p>${draft.stops.map(id=>escapeHTML(S.cities[id].name)).join(' → ')}</p><p>${cost.invalid||'新增桥梁 '+cost.bridge+'，隧道 '+cost.tunnel}${invalid?' · 条件不足，不能应用':''}</p><button class="primary" onclick="confirmRemoveStop()" ${invalid?'disabled':''}>确认移除</button><button onclick="cancelDraft(false);closeModal()" style="margin-left:15px">取消</button>`);}
function offerStopUndo(lineId,removal){let l=S.lines.find(x=>x.id===lineId);stopUndo={lineId,before:removal.before,after:[...l.stops],name:removal.name,expires:performance.now()+8000};$('toast').innerHTML=escapeHTML('已移除 '+removal.name)+' <button id="undo-stop" onclick="undoStopRemoval()">撤销</button>';$('toast').classList.add('show','undo-enabled');clearTimeout(toastTimer);toastTimer=setTimeout(()=>{$('toast').classList.remove('show','undo-enabled');},8000);}
function undoStopRemoval(){let u=stopUndo,l=u&&S.lines.find(x=>x.id===u.lineId);if(!u||performance.now()>u.expires||!l||l.retiring||l.stops.join(',')!==u.after.join(',')){stopUndo=null;return toast('线路已再次修改，无法撤销这一步');}for(let v of S.vehicles.filter(v=>v.line===l.id))unloadForEdit(v,l);l.stops=[...u.before];stopUndo=null;selected={type:'line',id:l.id};showDetails();updateUI();save();toast('已恢复 '+u.name+' 的停靠');}
function confirmRemoveStop(){closeModal();commitDraft(true);}
function showVehicleDetails(){let v=S.vehicles.find(x=>x.id===selected?.id),el=$('details');if(!v){clearSelection();return;}let l=S.lines.find(x=>x.id===v.line);let groups={};for(let p of v.people){let k=p.schoolId!==undefined?'s:'+p.dest+':'+p.schoolReturn:(p.eventId||p.cardId||p.fixedDestination)?(typeof specialPassengerMark130==='function'?specialPassengerMark130(p):'')+':'+p.dest:p.color+'-'+p.shape+':r'+(p.destRegion??'any');(groups[k]??=[]).push(p);}el.hidden=false;el.innerHTML=`<button class="close" onclick="clearSelection()">×</button><h3>${TYPES[v.type].name} #${v.id}</h3><div class="detail-sub">${escapeHTML(l.name)} · ${isTrain(v.type)?v.cars+'节编组':v.dwell>0?'停站上下客':'运行中'}</div><div class="metric-grid"><div><small>实际载客</small><b>${v.people.length}<small> / ${vehCap(v)}人</small></b></div><div><small>载客率</small><b>${Math.round(v.people.length/vehCap(v)*100)}%</b></div></div><p class="detail-sub" style="margin-top:15px">车内旅客目的地</p>${Object.entries(groups).map(([k,ps])=>`<button class="passenger-row" onclick="focusPassenger('${specialPassengerMark130(ps[0])?'event':'normal'}',${ps[0].dest??-1},${ps[0].color},${ps[0].shape},${ps[0].destRegion??'null'})" aria-label="定位目的城市"><span style="color:${COLORS[ps[0].color]}">${passengerLabel(ps[0])}</span><span>${ps.length}人 ›</span></button>`).join('')||'<p class="detail-sub">当前空车。</p>'}<div class="detail-actions"><button onclick="selectLine(${l.id})">查看所属线路</button></div>`;}
function clearSelection(){hideJunction();selected=null;$('details').hidden=true;updateUI()}
function selectDemand(id,color,shape){selected={type:'demand',id,color,shape};showDetails();toast('已标记所有匹配城市 · 同色同形均可到达')}
function expandCity(id){let c=S.cities[id],price=c.expand?1100:700;if(c.expand>=2)return;if(S.points<price)return toast('资金不足');S.points-=price;c.expand++;showDetails();save();toast('候车容量已扩充')}
function hubCity(id){let c=S.cities[id],year=formatDate().year,limit=Math.min(4,year+1),price=250+S.hubCount*100;if(c.hub)return;if(S.hubCount>=limit)return toast('本年度枢纽名额已用完，上限 '+limit+' 座');if(S.points<price)return toast('资金不足：需要 '+price+' 点');if(!confirm('将'+c.name+'升级为固定枢纽？容量翻倍，候车耐心消耗降低35%，不能转移。'))return;S.points-=price;S.hubCount++;c.hub=true;showDetails();save()}
function renameLine(id){let l=S.lines.find(l=>l.id===id);openModal(`<h2>线路设置</h2><p>线路名称</p><input id="linename" maxlength="16" value="${escapeHTML(l.name)}"><div class="colors">${LINECOL.map(c=>`<button style="background:${c}" onclick="setLineColor(${id},'${c}')" aria-label="选择颜色"></button>`).join('')}</div><button class="primary" onclick="applyName(${id})">保存设置</button>`)}
function setLineColor(id,c){S.lines.find(l=>l.id===id).color=c;updateUI()}
function applyName(id){S.lines.find(l=>l.id===id).name=$('linename').value.trim()||'未命名线路';closeModal();showDetails();updateUI()}
function deleteLine(id,dragConfirmed=false){let l=S.lines.find(l=>l.id===id);if(l.retiring)return toast('线路正在撤出');if(!dragConfirmed&&!confirm('撤销'+l.name+'？载具到下一站卸客后回收，完成后返还线路名额，桥隧保留。'))return;l.retiring=true;if(!S.vehicles.some(v=>v.line===id))S.lines=S.lines.filter(x=>x.id!==id);clearSelection();save();toast('线路开始撤出 · 载具将在下一站卸客');updateUI();}

function transportIcon(type){let body=type==='bus'?'<rect x="8" y="12" width="48" height="23" rx="6" fill="currentColor"/><path d="M14 18h9v9h-9zm13 0h9v9h-9zm13 0h9v9h-9z" fill="white" opacity=".8"/><circle cx="19" cy="36" r="5" fill="#334b4e"/><circle cx="46" cy="36" r="5" fill="#334b4e"/>':isTrain(type)?'<path d="M5 16h36q11 0 18 17H5z" fill="currentColor"/><path d="M10 20h8v6h-8zm12 0h8v6h-8zm12 0h7l5 6H34z" fill="white"/><path d="M7 37h50" stroke="#aab9af" stroke-width="2"/>':'<path d="M60 23 38 19 24 5h-6l9 15-16 1-7-7H1l5 11-5 10h3l7-7 16 1-9 15h6l14-14 22-4z" fill="currentColor"/>';return '<svg viewBox="0 0 64 48" class="transport-icon" aria-hidden="true">'+body+'</svg>';}
function buyAndAdd(id){let l=S.lines.find(l=>l.id===id);if(!l||l.retiring)return;let price=TYPES[l.type].vehicle;if(S.points<price)return toast('资金不足，需要 '+price+' 点');spend(price,'vehicles','购买'+TYPES[l.type].name);S.inventory[l.type]++;addStockAsset(l.type,{cars:isTrain(l.type)?2:1,investment:price});addVehicle(id);updateUI();save();}
function shop(tab='vehicles'){openModal(`<div class="modal-head"><div><span class="eyebrow">TRANSPORT DEPOT / 测试版</span><h2>交通采购</h2></div><div><b>¥${S.points}</b><button class="close" onclick="closeModal()">×</button></div></div><p>已有车辆可以在线路之间回收调配。初期资金紧张，先改善已有线路。</p><div class="shop-grid">${products().map(p=>`<div class="product">${transportIcon(p.key.slice(2))}<b>${p.name}</b><small>${p.desc}</small><button onclick="purchase('${p.key}')" ${S.points<p.price||p.locked?'disabled':''}>${p.locked?'尚未开放':'¥'+p.price+'　购买'}</button></div>`).join('')}</div><p>桥梁 ¥1500 / 座，隧道 ¥2200 / 座：拉线时自动报价，无需先买道具。<br>测试版暂不扣每日运营费；不出售城市升级，完成交通任务推动繁荣。</p><button class="secondary" onclick="showFinance()">查看收支账本 →</button>`);}

function products(){return Object.entries(TYPES).map(([t,v])=>({key:'v-'+t,name:v.name,desc:`库存 ${S.inventory[t]} · ${isTrain(t)?'初始36人，可增加车厢':t==='air'?'48人，适合远程出行':'14人，适合短途接驳'}`,price:v.vehicle,locked:!S.unlocked.includes(t)}));}

function purchase(key){let p=products().find(p=>p.key===key);if(!p||p.locked||S.points<p.price)return;spend(p.price,'vehicles','采购'+p.name);S.inventory[key.slice(2)]++;addStockAsset(key.slice(2),{cars:isTrain(key.slice(2))?2:1,investment:p.price});save();shop();updateUI();}

function reward(points){let unlocked=[];for(let [type,day] of [['rail',30],['air',60]])if(S.day>=day&&!S.unlocked.includes(type)){S.unlocked.push(type);S.limits[type]=isTrain(type)?2:1;unlocked.push(TYPES[type].name);}S.lastSettlement=S.day;toast('十天补助 +¥'+points+(unlocked.length?' · 已开放'+unlocked.join('、')+'采购':''));updateUI();save();}

function takeReward(k){S.inventory[k]++;closeModal();updateUI();toast('补给已领取')}
function help(){openModal(`<div class="modal-head"><h2>测试版调度手册</h2><button class="close" onclick="closeModal()">×</button></div><div class="help-grid"><div><p><b>原来的拉线操作</b><br>从城市拖向城市；首尾可延长，途径点可摘下。多线城市点开选择线路，再拖动。新增路段先报价，桥隧一并确认。</p><p><b>每位乘客有具体目的地</b><br>独立小方块表示乘客，颜色对应目的地。点击城市的候车列表可定位目标；同色城市不再互相替代。旅游、居住、商业、工业影响需求方向。</p><p><b>城市任务</b><br>每城同时一个任务。旅游/商业/工业统计送达，居住城统计居民从本城出发并到达目的地。奖金自动领取；两项任务后升一级，最高三级。</p></div><div><p><b>资金</b><br>开局500，公交180。票款按起终点直线距离1/2/3结算，换乘不重复收费。十天补助100。桥150、隧道220，已建同类通道可复用。暂不扣运营费。</p><p><b>城市与等待</b><br>新城16天起逐步发现，待接入时不产生乘客。接入后有45秒宽限。超时180秒后8秒警告，扣一条生命，之后保护45秒。</p><p><b>操作</b><br>空格暂停，滚轮或双指缩放，拖空白平移。购物、任务总览和编辑暂停模拟；横竖屏均可。第30/60天开放高铁/航空购买。</p></div></div><div class="construction-actions"><button onclick="showFinance()">收支账本</button><button class="danger" onclick="if(confirm('重新开始测试？正式版存档不受影响。'))newGame()">重新测试</button><a href="../">返回正式版</a></div>`);}

function displayLineDistance(p,a,b,l){let distance=Infinity,previous=lanePoint(a,b,l,0);for(let i=1;i<=24;i++){let next=lanePoint(a,b,l,i/24);distance=Math.min(distance,segDist(p,previous,next));previous=next;}return distance;}
function routeHit(p){let best=null,d=(globalThis.ROUTE_PX||12)/view.scale,preferred=selected?.type==='line'?selected.id:selected?.type==='stop'?selected.line:null;let candidates=S.lines.filter(l=>!l.retiring).sort((a,b)=>(a.id===preferred?-1:0)-(b.id===preferred?-1:0));for(let l of candidates){for(let i=1;i<l.stops.length;i++){let a=S.cities[l.stops[i-1]],b=S.cities[l.stops[i]],dd=displayLineDistance(p,a,b,l);if(dd<d){best={l,index:i};d=dd;}}if(best&&l.id===preferred)return best;}return best;}
function popStation(c,color){popEvents.push({x:c.x,y:c.y,r:radius(c)+5,color,at:performance.now()});}
function elasticTouch(p,previous){let direct=hitCity(p);if(direct&&Math.hypot(direct.x-p.x,direct.y-p.y)<Math.max(radius(direct)+5,12/view.scale))return direct;if(!previous)return null;let nearest=null,best=Infinity;for(let c of S.cities){if(c.removed)continue;if(c.id===gesture.lastHover)continue;let r=Math.max(radius(c)+4,10/view.scale);if(segDist(c,previous,p)<r&&Math.hypot(c.x-previous.x,c.y-previous.y)>r){let d=Math.hypot(c.x-previous.x,c.y-previous.y);if(d<best){best=d;nearest=c;}}}return nearest;}
function updateElastic(p){let previous=gesture.cursor;gesture.cursor=p;gesture.loose=true;let c=elasticTouch(p,previous);if(!c){gesture.lastHover=null;draftBar();$('drawtext').textContent='拖过已有城市摘下停靠 · 拖过新城市接入';return;}if(c.id===gesture.lastHover)return;gesture.lastHover=c.id;let idx=draft.stops.indexOf(c.id);if(idx>=0){if(draft.stops.length<=2){$('drawtext').textContent='至少保留两站 · 不会撤销整条线';gesture.loose=false;return;}draft.stopRemoval??={before:[...gesture.baseStops],name:c.name};draft.stopRemoval.name=c.name;draft.stops.splice(idx,1);gesture.slot=Math.min(idx,draft.stops.length);gesture.loose=false;popStation(c,'#bb7359');draftBar();$('drawtext').textContent='已摘下 '+c.name+' · 松手生效';}else{let slot=Math.max(0,Math.min(draft.stops.length,gesture.slot));draft.stops.splice(slot,0,c.id);gesture.slot=slot+1;gesture.loose=false;popStation(c,draft.color);draftBar();$('drawtext').textContent='已接入 '+c.name+' · 松手生效';}}

function addDraftCity(c){if(!draft)return;if(draft.stops.at(-1)===c.id)return;let existing=draft.stops.indexOf(c.id);if(existing>=0){draft.stops=draft.stops.slice(0,existing+1);draftBar();return;}draft.stops.push(c.id);draftBar()}
function cityLines(id){return S.lines.filter(l=>!l.retiring&&l.stops.includes(id));}
function hideJunction(){junctionOpen=false;let picker=$('junction-picker');if(picker)picker.hidden=true;}
function showJunction(id,preferred=null){let c=S.cities[id],lines=cityLines(id);if(!c||!lines.length)return;selected={type:'junction',id,preferred};junctionOpen=true;$('details').hidden=true;let el=$('junction-picker');el.hidden=false;let width=Math.min(280,W-24),height=Math.min(315,90+lines.length*48);el.style.width=width+'px';el.style.left=Math.max(12,Math.min(W-width-12,toScreen(c).x+20))+'px';el.style.top=Math.max(83,Math.min(H-height-15,toScreen(c).y+20))+'px';el.innerHTML=`<div class="junction-heading"><div><b>${escapeHTML(c.name)}</b><small>选择线路，或查看城市任务</small></div><button onclick="clearSelection()" aria-label="关闭线路选择">×</button></div><button class="junction-city-task" onclick="openCity(${id})">城市任务与候车 →</button><div class="junction-lines">${lines.map(l=>`<div class="junction-line ${l.id===preferred?'chosen':''}"><button onclick="chooseJunctionLine(${l.id},${id})"><i style="background:${l.color}"></i><span>${escapeHTML(l.name)}<small>${TYPES[l.type].name} · ${l.stops.length}站</small></span></button><button class="junction-drag" data-junction-line="${l.id}" data-junction-city="${id}" aria-label="选择${escapeHTML(l.name)}并拉线">拉线 ↗</button></div>`).join('')}</div>`;}
function chooseJunctionLine(lineId,cityId,notify=true){let l=S.lines.find(l=>l.id===lineId&&!l.retiring&&l.stops.includes(cityId));if(!l)return toast('该线路已改变，请重新选择');selectLine(lineId);if(notify)toast('已选 '+l.name+' · 从'+S.cities[cityId].name+'向外拖动');}
function startJunctionDrag(e,lineId,cityId){let l=S.lines.find(l=>l.id===lineId&&!l.retiring),c=S.cities[cityId];if(!l||!c||!l.stops.includes(cityId)||draft||bridgeDraft||pointers.size)return;e?.preventDefault();e?.stopPropagation();hideJunction();selected=null;$('details').hidden=true;if(typeof uxCancelAutoMove==='function')uxCancelAutoMove();beginDraft(l.type,l.id);draft.tapEdit132=true;draftBar();$('drawtext').textContent='已选 '+l.name+' · 拖动这条线，确认后应用';}
function beginPointer(e){if(handleEngineeringPointer('down',e))return;hideJunction();cv.setPointerCapture(e.pointerId);pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2){if(draft?.tapEdit132&&gesture?.snapshot132)draft={...gesture.snapshot132,stops:[...gesture.snapshot132.stops]};if(gesture?.createdDraft)cancelDraft(false);let arr=[...pointers.values()];gesture={kind:'pinch',dist:Math.hypot(arr[0].x-arr[1].x,arr[0].y-arr[1].y),scale:view.scale,x:view.x,y:view.y,cx:(arr[0].x+arr[1].x)/2,cy:(arr[0].y+arr[1].y)/2};return;}
let p=toWorld(e),rh=routeHit(p),c=hitCity(p);let lock=editLineLock13();if(lock&&rh?.l?.id!==lock.id)rh=null;if(c&&rh&&Math.hypot(c.x-p.x,c.y-p.y)>radius(c)+5)c=null;
gesture={kind:'tap',start:{x:e.clientX,y:e.clientY},p,c,rh,moved:false,vx:view.x,vy:view.y,hadDraft:!!draft};if(draft?.tapEdit132){gesture.draftStops=[...draft.stops];gesture.snapshot132={...draft,stops:[...draft.stops]};let l=S.lines.find(l=>l.id===draft.original);if(!l){cancelDraft(false);gesture.kind='none';return;}if(c&&draft.stops.includes(c.id)){Object.assign(gesture,{kind:'city-edit-pending132',cityLine:l,cityIndex:draft.stops.indexOf(c.id),baseStops:[...draft.stops]});}else if(!c&&rh?.l.id===l.id){Object.assign(gesture,{kind:'elastic-pending132',baseStops:[...draft.stops],slot:rh.index,cursor:p});}else gesture.kind='pan';return;}if(draft){if(c)addDraftCity(c);gesture.kind='draft';return;}
if(c){let preferred=selected?.type==='line'?selected.id:selected?.type==='stop'?selected.line:selected?.type==='junction'?selected.preferred:null;let options=S.lines.filter(l=>!l.retiring&&l.stops.includes(c.id)&&(!lock||l.id===lock.id));if(lock&&!options.length){gesture.kind='pan';return;}let l=options.find(l=>l.id===preferred)||(options.length===1?options[0]:null);if(l){gesture.cityLine=l;gesture.cityIndex=l.stops.indexOf(c.id);}else if(options.length>1)gesture.ambiguousLines=options;}else if(!rh)gesture.kind='pan';}
function movePointer(e){if(handleEngineeringPointer('move',e))return;if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(gesture?.kind==='pinch'){if(pointers.size!==2)return;let arr=[...pointers.values()],d=Math.hypot(arr[0].x-arr[1].x,arr[0].y-arr[1].y),s=Math.max(minScale(),Math.min(2.5,gesture.scale*d/gesture.dist)),cx=(arr[0].x+arr[1].x)/2,cy=(arr[0].y+arr[1].y)/2;view.x=cx-(gesture.cx-gesture.x)*s/gesture.scale;view.y=cy-(gesture.cy-gesture.y)*s/gesture.scale;view.scale=s;return;}if(!gesture)return;let p=toWorld(e),moved=Math.hypot(e.clientX-gesture.start.x,e.clientY-gesture.start.y)>8;if(moved)gesture.moved=true;if(gesture.kind==='pan'){view.x=gesture.vx+e.clientX-gesture.start.x;view.y=gesture.vy+e.clientY-gesture.start.y;return;}
if(moved&&gesture.kind==='city-edit-pending132')gesture.kind='city-edit';if(moved&&gesture.kind==='elastic-pending132')gesture.kind='elastic';
if(gesture.kind==='tap'&&moved){if(gesture.ambiguousLines){showJunction(gesture.c.id);gesture.kind='choose-line';return;}if(gesture.cityLine){let l=gesture.cityLine;beginDraft(l.type,l.id);gesture.baseStops=[...l.stops];gesture.kind='city-edit';gesture.createdDraft=true;}
else if(gesture.c){let type=S.unlocked.find(t=>S.limits[t]>S.lines.filter(l=>l.type===t).length);if(!type){toast('选中要调整的线路，拖动城市或城市旁的线段即可编辑');gesture.kind='none';return;}beginDraft(type);draft.stops=[gesture.c.id];gesture.kind='draft';gesture.createdDraft=true;}
else if(gesture.rh){let {l,index}=gesture.rh;beginDraft(l.type,l.id);gesture.baseStops=[...l.stops];gesture.slot=index;gesture.cursor=gesture.p;gesture.kind='elastic';gesture.createdDraft=true;}else gesture.kind='pan';}
if(gesture.kind==='draft'&&draft){draft.pointer=p;let c=hitCity(p);if(c)addDraftCity(c);draftBar();}
if(gesture.kind==='elastic'&&draft){draft.pointer=null;updateElastic(p);}
if(gesture.kind==='city-edit'&&draft){let origin=gesture.c,target=hitCity(p);draft.stops=[...gesture.baseStops];delete draft.stopRemoval;delete draft.extensionPointer;draft.pointer=null;if(target?.id===origin.id){draftBar();$('drawtext').textContent='已回到原位 · 松手取消';return;}if(target&&!gesture.baseStops.includes(target.id)){let slot=gesture.cityIndex===0?0:gesture.cityIndex+1;draft.stops.splice(slot,0,target.id);popStation(target,draft.color);draftBar();$('drawtext').textContent='接入 '+target.name+' · 松手生效';}else if(!target&&(gesture.cityIndex===0||gesture.cityIndex===gesture.baseStops.length-1)){draft.extensionPointer={city:origin.id,p};draft.pointer=p;draftBar();$('drawtext').textContent='继续拖到新城市延伸线路 · 松到空白处不改变线路';}else{draft.stops=draft.stops.filter(id=>id!==origin.id);draft.stopRemoval={before:[...gesture.baseStops],name:origin.name};draftBar();$('drawtext').textContent=draft.stops.length<2?'至少保留两站 · 不会撤销整条线':'松手摘下 '+origin.name+' · 拖回原位取消';}}
}

function inDeleteDrop(e){let r=$('delete-drop').getBoundingClientRect();return e.clientX>=r.left-15&&e.clientX<=r.right+15&&e.clientY>=r.top-15&&e.clientY<=r.bottom+15;}
function showDeleteDrop(on){$('delete-drop').hidden=!on;}
function cancelDraft(notify=true){draft=null;$('drawbar').hidden=true;showDeleteDrop(false);if(notify)toast('已取消线路修改');}
function finishPointer(e){if(handleEngineeringPointer('up',e))return;pointers.delete(e.pointerId);if(!gesture)return;
if(e.type==='pointercancel'){if(draft?.tapEdit132&&gesture.snapshot132)draft={...gesture.snapshot132,stops:[...gesture.snapshot132.stops]};if(gesture.createdDraft)cancelDraft(false);showDeleteDrop(false);gesture=null;return;}
if(gesture.kind==='tap'&&!gesture.moved){let bridge=hitBridge(gesture.p);if(!gesture.c&&bridge){openBridge(bridge.id);gesture=null;return;}if(gesture.c){let lineId=selected?.type==='line'?selected.id:selected?.type==='stop'?selected.line:null;let l=S.lines.find(l=>l.id===lineId);if(cityLines(gesture.c.id).length>1)showJunction(gesture.c.id,lineId);else{selected=l&&l.stops.includes(gesture.c.id)?{type:'stop',id:gesture.c.id,line:l.id}:{type:'city',id:gesture.c.id};showDetails();}}else{let hit=S.vehicles.find(v=>{let pos=vehiclePose(v);return pos&&Math.hypot(pos.x-gesture.p.x,pos.y-gesture.p.y)<20/view.scale;});if(hit){selected={type:'vehicle',id:hit.id};showVehicleDetails();}else if(gesture.rh)selectLine(gesture.rh.l.id);else clearSelection();}}
if(draft){draft.pointer=null;let original=draft.original;
if(gesture.createdDraft&&gesture.moved){
if(original&&S.lines.find(l=>l.id===original)?.stops.join(',')===draft.stops.join(',')){cancelDraft(false);selectLine(original);}
else if(draft.stops.length<2){cancelDraft(false);if(original){selectLine(original);toast('线路至少保留两站，本次回拖未生效。移除单站请点击线路详情中的“移除此站”。');}}
else{let cost=draftCost();if(cost.invalid||cost.cash>S.points){toast(cost.invalid||'资金不足，本次拖动未生效');cancelDraft(false);}
else if(cost.cash||cost.bridge||cost.tunnel){draftBar();toast('线路已规划，点击查看报价后确认建设');}
else commitDraft();}}
else draftBar();}
showDeleteDrop(false);if(!pointers.size)gesture=null;}
cv.addEventListener('pointerdown',beginPointer);cv.addEventListener('pointermove',movePointer);cv.addEventListener('pointerup',finishPointer);cv.addEventListener('pointercancel',finishPointer);
cv.addEventListener('wheel',e=>{e.preventDefault();let p=toWorld(e),s=Math.max(minScale(),Math.min(2.5,view.scale*Math.exp(-e.deltaY*.001)));let k=s/view.scale;view.scale=s;view.x=e.clientX-(e.clientX-view.x)*k;view.y=e.clientY-(e.clientY-view.y)*k},{passive:false});
$('junction-picker').addEventListener('click',e=>{let btn=e.target.closest('[data-junction-line]');if(btn)startJunctionDrag(e,+btn.dataset.junctionLine,+btn.dataset.junctionCity);});
try{orientationHintDismissed=localStorage.getItem('transit04-hint-off')==='1'}catch{}$('dismiss-orientation').onclick=()=>{orientationHintDismissed=true;try{localStorage.setItem('transit04-hint-off','1')}catch{}syncOrientation();};$('landscape-enter').onclick=enterLandscape;$('fullscreen').onclick=enterLandscape;
$('pause').onclick=()=>{S.paused=!S.paused;updateUI();save()};$('speed').onclick=()=>{S.speed=S.speed===1?2:S.speed===2?4:1;updateUI()};$('help').onclick=help;$('shop').onclick=()=>shop();$('newroute').onclick=chooseType;$('overview').onclick=fit;$('drawcancel').onclick=()=>cancelDraft();$('drawdone').onclick=()=>commitDraft();$('route-list').onclick=e=>{let row=e.target.closest('[data-line]');if(row)selectLine(+row.dataset.line)};$('collapse').onclick=()=>{let c=$('routes').classList.toggle('collapsed');$('collapse').textContent=c?'+':'−';$('collapse').setAttribute('aria-expanded',String(!c))};
window.addEventListener('resize',resize);window.addEventListener('beforeunload',()=>save());document.addEventListener('visibilitychange',()=>{if(document.hidden&&!window.transitNativeLifecycle13){S.paused=true;save()}updateUI()});document.addEventListener('keydown',e=>{if(e.target.tagName==='INPUT')return;if(e.code==='Space'){e.preventDefault();S.paused=!S.paused;updateUI()}if(e.code==='Escape'){if(modalOpen)closeModal();else if(draft){cancelDraft(false)}else clearSelection()}});


const FEATURES=[{name:'居住',verb:'居民通勤',desc:'送本城居民到其他城市，成功抵达才计数。',color:'#8aaf8f'},{name:'旅游',verb:'游客送达',desc:'将其他城市的游客送达本城。',color:'#cba26a'},{name:'商业',verb:'商业往来',desc:'将外地乘客送达本城商业区。',color:'#779caf'},{name:'工业',verb:'员工到岗',desc:'将周边居民送达本城工作。',color:'#9a9baf'}];
const LEVELS=['小镇','小城','大城市'];
function ledgerEntry(amount,label){S.history.unshift({day:Math.floor(S.day)+1,amount,label});S.history=S.history.slice(0,40);}
function credit(amount,category,label){if(!Number.isFinite(amount)||amount<=0)return;S.points=Math.round((S.points+amount)*100)/100;S.ledger[category]=Math.round(((S.ledger[category]||0)+amount)*100)/100;if(category!=='fares')ledgerEntry(amount,label);}
function spend(amount,category,label){if(!Number.isFinite(amount)||amount<0||amount>S.points)throw new Error('Invalid expenditure');if(!amount)return;S.points=Math.round((S.points-amount)*100)/100;S.ledger[category]=Math.round(((S.ledger[category]||0)+amount)*100)/100;ledgerEntry(-amount,label);}
function missionSpec(c){let step=c.mission.step;if(step>=6)return null;return {goal:[12,24,45,70,100,140][step],reward:[60,100,90,140,120,180][step],upgrade:step===1||step===3,verb:FEATURES[c.shape].verb};}
function completeTrip(p,dest){let fare=p.fare||1;credit(fare,'fares','票款');dest.arrivals++;let origin=S.cities[p.origin];if(origin)origin.departures++;if(dest.shape!==0)advanceMission(dest);if(origin?.shape===0)advanceMission(origin);}
function advanceMission(c){let spec=missionSpec(c);if(!spec||c.dormant)return;c.mission.progress++;c.growth=Math.round(((c.mission.step%2)+Math.min(1,c.mission.progress/spec.goal))*50);if(c.mission.progress<spec.goal)return;credit(spec.reward,'tasks',c.name+' · '+spec.verb);c.mission.step++;c.mission.completed++;c.mission.progress=0;if(spec.upgrade&&c.size<2){c.size++;c.capacity=[24,40,64][c.size];credit(600,'tasks',c.name+'繁荣奖励');c.growth=0;popEvents.push({x:c.x,y:c.y,r:radius(c)+10,color:'#83a76a',at:performance.now()});toast(c.name+'升级为'+LEVELS[c.size]+' · 奖励 ¥'+(spec.reward+600)+'，客流逐渐增长');}else toast(c.name+'完成任务 · +¥'+spec.reward);c.rewardUntil=S.day+1.5;updateUI();save();}
function missionHTML(c){let spec=missionSpec(c);if(c.dormant)return `<div class="city-mission"><span class="eyebrow">待接入城镇</span><h4>${FEATURES[c.shape].name}发展机会</h4><p>拖动线路连接本城，确认建设后开放。接入前不产生乘客，也不消耗生命。</p><small>接入后45秒宽限，客流在五天内逐渐增加。</small></div>`;if(!spec)return `<div class="city-mission"><span class="eyebrow">城市发展已完成</span><h4>繁荣的${FEATURES[c.shape].name}城市</h4><p>六项任务已完成，继续服务客流可获得票款。</p></div>`;let n=c.mission.progress;return `<div class="city-mission"><div class="mission-heading"><span class="eyebrow">交通任务 ${c.mission.step+1} / 6</span><b>+¥${spec.reward+(spec.upgrade?600:0)}</b></div><h4>${spec.verb}</h4><p>${FEATURES[c.shape].desc}</p><div class="mission-progress"><i style="width:${Math.min(100,n/spec.goal*100)}%"></i></div><div class="mission-heading"><span>${n} / ${spec.goal} 人</span><small>${spec.upgrade?'升级并扩容，含繁荣奖600':'奖金自动到账'}</small></div></div>`;}
function openCity(id){hideJunction();selected={type:'city',id};showDetails();}
function focusDestination(id){let c=S.cities[id];if(!c)return;openCity(id);popStation(c,COLORS[c.color]);toast('目的地：'+c.name+' · '+FEATURES[c.shape].name+'城市');}
function showFinance(){let l=S.ledger;openModal(`<div class="modal-head"><div><span class="eyebrow">CITY ECONOMY / 测试账本</span><h2>资金 ¥${S.points}</h2></div><button class="close" onclick="closeModal()">×</button></div><div class="finance-summary"><span>初始资金 <b>5000</b></span><span>票款 <b>+${l.fares}</b></span><span>城市任务 <b>+${l.tasks}</b></span><span>十天补助 <b>+${l.subsidy}</b></span><span>线路与工程 <b>−${l.construction}</b></span><span>车辆采购 <b>−${l.vehicles}</b></span></div><p>起终点距离决定票款：近程10、中程20、远程30。换乘不重复收费。测试版暂不扣每日运营费。</p><div class="ledger-list">${S.history.map(e=>`<div class="quote-row"><span>第${e.day}天 · ${escapeHTML(e.label)}</span><b class="${e.amount>0?'income':''}">${e.amount>0?'+':''}${e.amount}</b></div>`).join('')||'<p>暂无建设或奖励记录，票款汇总显示在上方。</p>'}</div><button class="secondary" onclick="shop()">返回采购</button>`);}
function showTasks(){openModal(`<div class="modal-head"><div><span class="eyebrow">CITY DEVELOPMENT</span><h2>城市交通任务</h2></div><button class="close" onclick="closeModal()">×</button></div><div class="task-cities">${S.cities.filter(c=>c.kind!=='bridgehead').map(c=>`<section><div class="mission-heading"><h3>${escapeHTML(c.name)}</h3><small>${FEATURES[c.shape].name} · ${LEVELS[c.size]}</small></div>${missionHTML(c)}<button onclick="closeModal();openCity(${c.id})">定位城市 →</button></section>`).join('')}</div>`);}
function drawMissionBadges(){for(let c of S.cities){let spec=missionSpec(c);if(c.dormant)continue;let label=c.rewardUntil>S.day?'奖金已到账':spec?c.mission.progress+'/'+spec.goal:'繁荣';let x=c.x,y=c.y-76-c.size*9;ctx.save();ctx.globalAlpha=.95;roundBody(x-28,y-9,56,17,5,c.rewardUntil>S.day?'#e5efda':'#fffdf6','#e1e6d8',.8);text(label,x,y+2,8,c.rewardUntil>S.day?'#577942':'#879274');ctx.restore();}}
function drawTree(x,y,k=1){ctx.save();ctx.translate(x,y);uprightHere();ctx.scale(k,k);ellipse({x:3,y:1,rx:7,ry:3},'#496b4d17');ctx.fillStyle='#9e9270';ctx.fillRect(-1,-5,2,8);ellipse({x:0,y:-8,rx:6,ry:8},'#9eb593');ellipse({x:-2,y:-10,rx:4,ry:6},'#b6c9a1');ctx.restore();}
function poly(points,fill,stroke){ctx.beginPath();points.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=.7;ctx.stroke();}}
function building(x,y,w,h,tone,roof,style='home'){let d=w*.36;ellipse({x:x+5,y:y+3,rx:w*.8,ry:4},'#41534713');poly([[x-w/2,y-h],[x+w/2,y-h],[x+w/2,y],[x-w/2,y]],tone);poly([[x+w/2,y-h],[x+w/2+d,y-h-d*.45],[x+w/2+d,y-d*.45],[x+w/2,y]],'#bfc9bd');if(style==='home'){poly([[x-w/2-2,y-h],[x,y-h-8],[x+w/2+2,y-h]],roof);poly([[x,y-h-8],[x+d,y-h-8-d*.45],[x+w/2+d+2,y-h-d*.45],[x+w/2+2,y-h]],roof);}else{poly([[x-w/2,y-h],[x-w/2+d,y-h-d*.45],[x+w/2+d,y-h-d*.45],[x+w/2,y-h]],roof);}ctx.fillStyle='#7e9ca2';for(let row=0;row<Math.max(1,Math.floor((h-5)/9));row++)for(let col=0;col<Math.max(1,Math.floor((w-4)/7));col++)ctx.fillRect(x-w/2+3+col*7,y-h+4+row*9,3,4);ctx.fillStyle='#9c927c';ctx.fillRect(x-2,y-6,4,6);if(style==='shop'){ctx.fillStyle=roof;ctx.fillRect(x-w/2,y-9,w,4);}}
function drawCityArt(c){ctx.save();ctx.translate(c.x,c.y);uprightHere();ctx.globalAlpha=(c.dormant?.38:1)*(globalThis.ART_ALPHA??1);let spread=34+c.size*9;ellipse({x:0,y:-36,rx:spread+7,ry:19+c.size*4},'#dfe7d55c');ellipse({x:3,y:-30,rx:spread,ry:12+c.size*4},'#d7dbc34a');ctx.strokeStyle='#e9e4d1';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(0,-15);ctx.lineTo(0,-41);ctx.moveTo(-spread+5,-28);ctx.lineTo(spread-5,-42);ctx.stroke();drawTree(-spread+2,-32,.8);if(c.shape===0){building(-14,-30,18,17,'#f1eee0','#b8856b');building(14,-42,16,19,'#f9f5e7','#c28d70');if(c.size>=1)building(29,-25,16,24,'#eee9da','#b18b72');if(c.size>=2)building(-31,-48,19,31,'#e8e8d9','#9ea99c');}else if(c.shape===1){building(-12,-31,23,19,'#f4efd9','#b98d69','shop');ctx.fillStyle='#b8c9bc';ctx.fillRect(19,-63,4,30);ellipse({x:21,y:-64,rx:10,ry:4},'#7195a0');ellipse({x:21,y:-68,rx:7,ry:3},'#e2e9dd');if(c.size>=1)building(-31,-48,19,26,'#f4ecd9','#c7a274');if(c.size>=2)building(33,-26,21,34,'#eae8d5','#a9b7a3','shop');}else if(c.shape===2){building(-13,-30,21,29+c.size*4,'#ebefe7','#9eb0ae','shop');building(15,-42,19,35+c.size*7,'#f0f1e9','#9cb0ab');if(c.size>=1)building(30,-23,19,28,'#e1e8e0','#a4b5ab','shop');if(c.size>=2)building(-34,-47,18,45,'#e7ece4','#97a9aa');}else{building(-13,-28,30,17,'#dce3db','#a1b1ac','flat');building(15,-43,24,19,'#e4e6dc','#93a5a1','flat');ctx.fillStyle='#b6a991';ctx.fillRect(28,-69,5,28);ctx.fillStyle='#d5c7ad';ctx.fillRect(28,-69,5,5);if(c.size>=1)building(-32,-48,23,21,'#dce1d6','#a9b4a2','flat');if(c.size>=2)building(33,-20,23,23,'#dce3da','#9daea3','flat');}drawTree(spread,-28,.65);ctx.restore();}

